package com.lore.zzal.pet.receipt;
import com.lore.zzal.pet.*;import com.lore.zzal.pet.dto.PetRequests;import com.lore.zzal.PetFixture;
import org.junit.jupiter.api.*;import java.time.Instant;import java.util.*;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class CareActionDeliveryServiceTest {
 final Instant now=Instant.parse("2026-10-18T03:00:00Z");
 PetService pets;ZzalPetRepository owners;ActionReceiptRepository receipts;CareActionDeliveryService service;ZzalPet pet;
 final Map<UUID,ActionReceipt> rows=new HashMap<>();
 @BeforeEach void setup(){pets=mock(PetService.class);owners=mock(ZzalPetRepository.class);receipts=mock(ActionReceiptRepository.class);pet=PetFixture.hatching(1L,"합성",null,"images/source",now);when(owners.findByIdForUpdate(10L)).thenReturn(Optional.of(pet));when(pets.refresh(1L,10L,now)).thenReturn(pet);when(receipts.findByPetIdAndRequestId(any(),any())).thenAnswer(i->Optional.ofNullable(rows.get(i.getArgument(1))));service=new CareActionDeliveryService(pets,owners,receipts,tools.jackson.databind.json.JsonMapper.builder().build());}
 PetRequests.Care request(UUID id){return new PetRequests.Care(CareAction.PET,null,id);}
 @Test void duplicateReplaysOccurrenceWithoutRepeatingCareAndUsesCurrentSleepingPet(){var id=UUID.randomUUID();var request=request(id);var motion=new CareMotionPlayback("PET","base","pet","BASIC",null);when(pets.care(1L,10L,CareAction.PET,null,now)).thenReturn(new PetService.Action(pet,List.of(),false,motion));when(receipts.saveAndFlush(any())).thenAnswer(i->{var row=(ActionReceipt)i.getArgument(0);rows.put(id,row);return row;});var first=service.care(1L,10L,request,now);org.springframework.test.util.ReflectionTestUtils.setField(pet,"sleepKind",SleepKind.NIGHT);var replay=service.care(1L,10L,request,now);assertThat(replay.pet().isSleeping()).isTrue();assertThat(replay.motionPlayback()).isEqualTo(first.motionPlayback());verify(pets,times(1)).care(1L,10L,CareAction.PET,null,now);verify(receipts,times(1)).saveAndFlush(any());}
 @Test void sameUuidDifferentStepIsConflictBeforeAction(){var id=UUID.randomUUID();var a=request(id);rows.put(id,new ActionReceipt(10L,id,CareActionDeliveryService.requestHash(a),"{}",now));assertThatThrownBy(()->service.care(1L,10L,new PetRequests.Care(CareAction.PET,FirstIntro.Step.PET,id),now)).isInstanceOf(com.lore.common.exception.BusinessException.class);verifyNoInteractions(pets);}
 @Test void otherOwnerCannotReadReceipt(){assertThatThrownBy(()->service.care(2L,10L,request(UUID.randomUUID()),now)).isInstanceOf(com.lore.common.exception.BusinessException.class);verifyNoInteractions(receipts,pets);}
 @Test void rejectedActionDoesNotWriteReceipt(){when(pets.care(1L,10L,CareAction.PET,null,now)).thenThrow(new com.lore.common.exception.BusinessException(com.lore.common.exception.ErrorCode.ZZAL_PET_SLEEPING));assertThatThrownBy(()->service.care(1L,10L,request(UUID.randomUUID()),now)).isInstanceOf(com.lore.common.exception.BusinessException.class);verify(receipts,never()).saveAndFlush(any());}
 @Test void recordedPetUuidCannotBeReusedByAnotherAction(){var id=UUID.randomUUID();rows.put(id,new ActionReceipt(10L,id,CareActionDeliveryService.requestHash(request(id)),"{}",now));assertThatThrownBy(()->service.care(1L,10L,new PetRequests.Care(CareAction.FEED,null,id),now)).isInstanceOf(com.lore.common.exception.BusinessException.class);verifyNoInteractions(pets);verify(receipts,never()).saveAndFlush(any());}

 @Test void nullAndNonPetRequestsKeepLegacyCaller(){service.care(1L,10L,new PetRequests.Care(CareAction.PET),now);service.care(1L,10L,new PetRequests.Care(CareAction.CLEAN),now);verify(pets).care(1L,10L,CareAction.PET,null,now);verify(pets).care(1L,10L,CareAction.CLEAN,null,now);verifyNoInteractions(owners,receipts);}
}
